/*
 * A041879  Denominators of continued fraction convergents to sqrt(461).
 * https://oeis.org/A041879
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, frac, easy
 * Formula:   a(n) = 48628220*a(n-15) + a(n-30) for n>29. The values are
 *            denominators of the convergents to sqrt(461), generated by the
 *            standard continued‑fraction recurrence
 * Range:     u8 n <= 4, u16 n <= 11, u32 n <= 17, u64 n <= 41, u128 n <= 75,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* The first 30 terms are computed via continued fraction, then
   extended by the above recurrence. */

#include <stdlib.h>
#include <stdbool.h>

static seq_t *cache = NULL;      // array of stored a(n)
static idx_t cache_len = 0;      // number of elements currently stored
static idx_t cache_cap = 0;      // allocated capacity
static bool initialized = false;

/* Keep the two previous numerator and denominator values for
   recurrence:  p_{k-2}, p_{k-1}  and  q_{k-2}, q_{k-1} */
static seq_t p_prev1, p_prev2;
static seq_t q_prev1, q_prev2;

/* Periodic part of the continued fraction of sqrt(461)
   (starting after a0=21).  Length 15. */
static const int periodic[15] = {
    2, 8, 10, 1, 1, 1, 1, 1, 1, 1, 1, 10, 8, 2, 42
};

seq_t a(idx_t n)
{
    if (!initialized) {
        /* Allocate initial space, at least enough for the first term. */
        cache_cap = (n < 64 ? 64 : n + 1);
        cache = (seq_t *)malloc(cache_cap * sizeof(seq_t));
        if (!cache) return (seq_t)0;   /* failure: fall back to zero */

        /* Initial values for k = -2, -1 (needed for recurrence) */
        p_prev2 = (seq_t)0;
        p_prev1 = (seq_t)1;
        q_prev2 = (seq_t)1;
        q_prev1 = (seq_t)0;

        /* a0 = 1  (denominator of first convergent) */
        seq_t a0 = (seq_t)21;
        seq_t q0 = a0 * q_prev1 + q_prev2;  /* 21*0 + 1 = 1 */
        seq_t p0 = a0 * p_prev1 + p_prev2;  /* 21*1 + 0 = 21 */

        cache[0] = q0;          /* store a(0) */
        cache_len = 1;          /* we have one element now */

        /* advance state for the next term (k = 1) */
        q_prev2 = q_prev1;  q_prev1 = q0;
        p_prev2 = p_prev1;  p_prev1 = p0;

        initialized = true;
    }

    if (n >= cache_len) {
        /* Ensure enough capacity */
        if (n + 1 > cache_cap) {
            cache_cap = (cache_cap * 2 > n + 1) ? cache_cap * 2 : n + 1;
            cache = (seq_t *)realloc(cache, cache_cap * sizeof(seq_t));
            if (!cache) return (seq_t)0;   /* failure: return zero */
        }

        for (idx_t k = cache_len; k <= n; ++k) {
            seq_t ak;
            if (k == 0) {
                ak = (seq_t)21;               /* a0 */
            } else {
                ak = (seq_t)periodic[(k - 1) % 15];
            }

            /* Compute next numerator / denominator */
            seq_t qk = ak * q_prev1 + q_prev2;
            seq_t pk = ak * p_prev1 + p_prev2;

            /* Store denominator */
            cache[cache_len++] = qk;

            /* Advance state */
            q_prev2 = q_prev1;  q_prev1 = qk;
            p_prev2 = p_prev1;  p_prev1 = pk;
        }
    }
    return cache[n];
}
